import json,sys,subprocess,hashlib
from pathlib import Path
O=Path(__file__).parent;py=sys.executable
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
rows=json.loads(Path(sys.argv[1]).read_text());all_events=[]
for cfg in rows:
 c=cfg['sid'][:6];cfg.update(pdf_local_path=str(O/(c+'_official.pdf')),text_path=str(O/(c+'_official.pdf.txt')),extra_evidence_paths=[str(O/(c+'_CNINFO_SEARCH.json'))]);cfg['fact_notes'] += ['Full implementation notice manually reviewed. Dates are explicit notice facts, not inferred from local action ex-date. d_source only bridges source factors; d_cash ordinary eligible-share entitlement; d_ref published reference-price decrement if stated.','Self-distributed holders and holding-period taxes are separately described in full notice. Frozen NET80 scenario is not investor-specific tax timing. No engine edits, historical run, trades or PIT claim.'];cp=O/(c+'_NOTICE_REVIEW_INPUT.json');cp.write_text(json.dumps(cfg,ensure_ascii=False,indent=2)+'\n');subprocess.run([py,str(O/'adapt_reviewed_notice_v2.py'),str(cp)],check=True);ep=O/('EXTRA_REVIEWED_EQUITY_EVENTS_'+c+'_V1.json');es=json.loads(ep.read_text());es[0]['evidence_hashes'][str(ep)]=sha(ep);all_events+=es
